package com.forgeci.application.organization;
import com.forgeci.domain.user.User; import com.forgeci.infrastructure.organization.*; import com.forgeci.infrastructure.user.UserRepository; import org.junit.jupiter.api.*; import org.mockito.Mockito; import static org.junit.jupiter.api.Assertions.*;
class OrganizationServiceTest { OrganizationRepository orgs=Mockito.mock(OrganizationRepository.class); OrganizationMemberRepository members=Mockito.mock(OrganizationMemberRepository.class); UserRepository users=Mockito.mock(UserRepository.class); OrganizationService service=new OrganizationService(orgs,members,users); @Test void createsOwnerMembership(){var u=new User("a@example.com","hash","Alice");Mockito.when(users.findById(Mockito.any())).thenReturn(java.util.Optional.of(u));Mockito.when(orgs.findBySlug("acme")).thenReturn(java.util.Optional.empty());Mockito.when(orgs.save(Mockito.any())).thenAnswer(i->i.getArgument(0));var o=service.create(u.getId(),"Acme","Acme");assertEquals("acme",o.getSlug());Mockito.verify(members).save(Mockito.any());} }
